INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'BRV_VERIFIED', 'SMS', NULL, 'DCL: payment of PKR {AMOUNT} received (BRV {BRV_NO}, {BRV_DATE}). Thank you.', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'BRV_VERIFIED' AND CHANNEL = 'SMS' AND BRNCH IS NULL);
INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'BRV_VERIFIED', 'WA', NULL, 'Dear {CUSTOMER_NAME}, Dewan Cement has received your payment of PKR {AMOUNT} (BRV {BRV_NO}, {BRV_DATE}).', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'BRV_VERIFIED' AND CHANNEL = 'WA' AND BRNCH IS NULL);
INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'BRV_VERIFIED', 'EMAIL', 'Payment received: BRV {BRV_NO}', 'Dear {CUSTOMER_NAME},' || CHR(10) || CHR(10) || 'Dewan Cement Limited has received your payment of PKR {AMOUNT} (BRV {BRV_NO}, {BRV_DATE}).' || CHR(10) || CHR(10) || 'Regards,' || CHR(10) || 'Dewan Cement Limited', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'BRV_VERIFIED' AND CHANNEL = 'EMAIL' AND BRNCH IS NULL);
INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'DO_ISSUED', 'SMS', NULL, 'DCL: DO {DO_NO} issued, {QTY} t {PRODUCT}. Show the DO at the plant gate.', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'DO_ISSUED' AND CHANNEL = 'SMS' AND BRNCH IS NULL);
INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'DO_ISSUED', 'WA', NULL, 'Dear {CUSTOMER_NAME}, Delivery Order {DO_NO} has been issued for {QTY} t {PRODUCT} (OC {OC_NO}).', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'DO_ISSUED' AND CHANNEL = 'WA' AND BRNCH IS NULL);
INSERT INTO MSG_TEMPLATE (TEMPLATE_CODE, CHANNEL, SUBJECT, BODY, ACTIVE, BRNCH, COMPC) SELECT 'DO_ISSUED', 'EMAIL', 'Delivery Order {DO_NO}', 'Dear {CUSTOMER_NAME},' || CHR(10) || CHR(10) || 'Delivery Order {DO_NO} has been issued for {QTY} t {PRODUCT} against order confirmation {OC_NO}.' || CHR(10) || CHR(10) || 'Regards,' || CHR(10) || 'Dewan Cement Limited', 'Y', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM MSG_TEMPLATE WHERE TEMPLATE_CODE = 'DO_ISSUED' AND CHANNEL = 'EMAIL' AND BRNCH IS NULL);
